function feeStatus(row, ctx) { const { paid, balance, settled } = invoiceBalance(row, ctx.rows('payments')); return { paid, balance, status: settled ? 'Paid' : paid > 0 ? 'Part-paid' : row.dueDate < today() ? 'Overdue' : 'Unpaid' }; }
