function UsersPage({ctx}) { return <UserManagement ctx={ctx} api={api} Modal={Modal}/>; }
function AuditPage({ ctx }) { const [logs, setLogs] = useState([]), [error, setError] = useState(''), [q, setQ] = useState(''), [detail, setDetail] = useState(null); useEffect(() => { api('/audit').then(setLogs).catch(e => setError(e.message)); }, []); const filtered = logs.filter(r => [r.actor, r.action, r.entity].some(x => String(x).toLowerCase().includes(q.toLowerCase()))); return <><PageTitle eyebrow="ACCOUNTABILITY" title="Audit trail" text="Review who changed institutional records, and when."><button className="btn" onClick={() => download('EMIS-audit.csv', asCSV(filtered, ['id', 'actor', 'action', 'entity', 'recordId', 'createdAt', 'beforeData', 'afterData']))}><Download size={16}/>Export audit log</button></PageTitle><ErrorBox error={error}/><section className="card"><div className="records-toolbar"><div className="table-search"><Search size={17}/><input value={q} onChange={e => setQ(e.target.value)} placeholder="Search actor, action or module…"/></div><span className="muted">Latest {logs.length} events · read only</span></div><div className="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Module</th><th>Details</th></tr></thead><tbody>{filtered.map(r => <tr key={r.id} onClick={() => setDetail(r)}><td>{new Date(r.createdAt).toLocaleString('en-GB')}</td><td><b>{r.actor}</b></td><td>{r.action}</td><td>{modules[r.entity]?.title || r.entity || 'Workspace'}</td><td><button className="text-btn">View change<ArrowUpRight size={13}/></button></td></tr>)}</tbody></table></div></section>{detail && <Modal title="Record change" subtitle={`${detail.actor} · ${detail.action} · ${new Date(detail.createdAt).toLocaleString()}`} onClose={() => setDetail(null)} wide><div className="modal-body"><div className="audit-diff">{[['Before', detail.beforeData], ['After', detail.afterData]].map(([label, value]) => <div key={label}><h3>{label}</h3><pre>{value ? JSON.stringify(JSON.parse(value), null, 2) : 'No record snapshot'}</pre></div>)}</div></div></Modal>}</>; }
function HelpPage({ ctx }) { return <><PageTitle eyebrow="GETTING STARTED" title="A connected college workspace." text="A practical guide to using your EMIS ERP."/><div className="help-intro"><GraduationCap size={40}/><div><h2>Start with the foundation. Build the full picture.</h2><p>All modules share a database. The academic year selector controls operational records, while departments, programs and staff are institution-wide.</p></div></div><div className="help-grid">{[['01', 'Set up the institution', 'Add official college details, departments, programs and faculty. Configure the academic year.', 'settings'], ['02', 'Bring students on board', 'Record enquiries and applications. Accept an application, then use Enroll student to create a linked profile.', 'admissions'], ['03', 'Run the academic cycle', 'Allocate courses, build the timetable, take attendance, schedule examinations and publish results.', 'courses'], ['04', 'Track fees and support', 'Issue invoices and record payments. Keep scholarship awards, income, expenditure and budgets up to date.', 'fees'], ['05', 'Maintain your evidence', 'Map applicable QAA requirements, attach documents, collect feedback and track IQAC actions.', 'evidence'], ['06', 'Review and report', 'Explore indicators, generate an annual reporting draft, and export the grouped enrollment annex.', 'reports']].filter(([, , , to]) => to === 'settings' || (to === 'reports' ? ctx.allAccess : can(ctx.user.role, to))).map(([n, title, text, to]) => <button className="help-card" key={n} onClick={() => ctx.go(to)}><span>{n}</span><h3>{title}</h3><p>{text}</p><ArrowUpRight size={18}/></button>)}</div><section className="card help-details"><SectionHead title="How to work confidently"/>{[['Academic-year history', 'Choose the relevant year before creating records. Use Academic years to preview and create linked enrollments for the next year. Previous attendance, results and invoices stay in their original year. Student logins follow these explicit links. Global profiles such as faculty and programs show their current state, not historical snapshots.'], ['Imports and exports', 'Each module can export CSV. Administrators and authorized module owners can import up to 500 rows using its template. Invalid imports are rolled back together. Use program codes, student numbers and invoice numbers in CSV imports. Download the template, validate the file, review its rows, then confirm the import. References without a unique code use the IDs shown in the dialog.'], ['Attendance', 'Choose a course and date, then mark the class. Present and Late count as attended; Excused is excluded. Records are unique per student, course and date.'], ['Marks and GPA', 'Pass/fail is derived from the examination pass mark. Enter grade points using the university’s approved scale. The app does not assume a universal GPA conversion or calculate an official CGPA. Faculty save drafts; the examination team publishes results.'], ['Finance', 'Open an invoice or payment record to print its invoice or receipt. Student payments are applied to invoices and cannot exceed the unpaid balance. Income totals use received payments plus other income vouchers. Scholarship awards are tracked separately and do not automatically reduce invoices. This is an operational finance register, not a statutory double-entry accounting or payroll system.'], ['Roles and privacy', 'Permissions are enforced on the server. Students see their own records. Faculty see assigned courses and their students. Program Directors are restricted to their assigned program. Other staff receive permissions for their modules.'], ['Evidence and reporting', 'Attach files up to 10 MB to a saved record. Annual reports follow the structure in the supplied EMIS document. Review official definitions, national/university benchmarks, the applicable QAA criteria and the submission template before using reports externally.'], ['Backups and production deployment', 'The included project README explains setup, full backups and restore. Before shared production use, configure HTTPS, review roles, import college records, test recovery and arrange institution-specific acceptance testing. Hosted access is not included in this build.']].map(([title, text]) => <details key={title}><summary>{title}<ChevronDown size={16}/></summary><p>{text}</p></details>)}</section></>; }
class ErrorBoundary extends React.Component {
    constructor(p) { super(p); this.state = { error: null }; }
    static getDerivedStateFromError(error) { return { error }; }
    render() { return this.state.error ? <div className="boot"><Logo /><h2>Something interrupted this view.</h2><p>Your saved records are safe.</p><button className="btn primary" onClick={() => { location.hash = 'overview'; location.reload(); }}>Return to the workspace</button></div> : this.props.children; }
}
export default function EmisWorkspace(){return <ErrorBoundary><App/></ErrorBoundary>;}
export { CollegeSetup, ImportModal, Dashboard, RecordsPage, RecordDrawer, AttendanceModal, Reports, SettingsPage, UsersPage, HelpPage, EquityPanel, AcademicPanel };
